export function getIeContact(nameOrId, existingMobile) {
  if (existingMobile && String(existingMobile).trim() !== '' && String(existingMobile).trim() !== 'null' && String(existingMobile).trim() !== 'undefined' && String(existingMobile).trim() !== 'N/A') {
    return String(existingMobile).trim();
  }
  if (!nameOrId) return '';
  const key = String(nameOrId).toLowerCase().trim().replace(/\s+/g, ' ');
  return USER_MASTER_CONTACTS[key] || USER_MASTER_CONTACTS[String(nameOrId).trim()] || '';
}

